import {screenshotTopics as baselineScreenshots,officialOnlyTopics as baselineOfficial} from '../reviewed/coverage.mjs';

// Availability is about registered content, never a learner's performance.
// This module does not import drafts or alter the original coverage module.
export const BASELINE_COUNTS=Object.freeze({headings:60,partial:12,planned:48,complete:0});
const deepFreeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(deepFreeze);Object.freeze(x);}return x;};
const clone=x=>JSON.parse(JSON.stringify(x));
const nonempty=x=>typeof x==='string'&&x.trim().length>0;
const unique=x=>[...new Set(x)];

// Only exact authored objective IDs belong here. Additional chapters are added
// when their authors supply stable IDs, not inferred from a title or keyword.
