const courseFor={bio:'BIO',gc:'GCHEM',oc:'OCHEM',pat:'PAT',rc:'RC',qr:'QR'};
const blockedReviewStates=new Set(['pending','failed','blocked','draft','unreviewed',false]);
const reviewed=r=>!!r&&r.reviewStatus==='internal-reviewed'&&r.verified!==false&&r.progressEligible!==false&&r.runtimeIntegrated!==false&&
  !Object.values(r.independentReview||{}).some(v=>blockedReviewStates.has(v&&typeof v==='object'?v.status:v));
function indexRecords(records,diagnostics,label){
  const map=new Map();
  for(const r of Array.isArray(records)?records:[]){if(!nonempty(r?.id))continue;if(map.has(r.id)){map.set(r.id,null);diagnostics.push(`Duplicate ${label} ID excluded: ${r.id}`);}else map.set(r.id,r);}
  return map;
}
function validItem(item,objectiveId,world,pool){
  const choices=item?.options||item?.choices;
  return reviewed(item)&&item.verified===true&&item.objectiveId===objectiveId&&item.world===world&&(!item.course||item.course===courseFor[world])&&item.pool===pool&&
    Array.isArray(choices)&&[4,5].includes(choices.length)&&choices.every(nonempty)&&Number.isInteger(item.answer)&&item.answer>=0&&item.answer<choices.length;
}
function inspectFacet(chapter,facet,route,objectives,items,guides){
  const reasons=[],objective=objectives.get(facet.objectiveId),guide=guides?.[facet.objectiveId];
  if(!route||route.available===false||route.availability==='planned'||route.runtimeIntegrated===false||(route.reviewStatus&&!reviewed(route)))reasons.push('Chapter is not an active registered route.');
  if(!route?.objectiveIds?.includes(facet.objectiveId))reasons.push('Objective is not assigned to that active route.');
  if(!reviewed(objective)||objective?.world!==chapter.world)reasons.push('Reviewed objective is not registered.');
  if(!reviewed(guide)||guide?.objectiveId!==facet.objectiveId||!nonempty(guide?.core)||!nonempty(guide?.workedExample?.prompt)||!nonempty(guide?.workedExample?.answer)||!Array.isArray(guide?.workedExample?.steps)||!guide.workedExample.steps.length)reasons.push('Reviewed instruction and worked example are not registered.');
  const ids=pool=>unique((Array.isArray(route?.[pool+'Ids'])?route[pool+'Ids']:[]).filter(id=>validItem(items.get(id),facet.objectiveId,chapter.world,pool)));
  const practiceIds=ids('practice'),checkIds=ids('check'),laterIds=ids('later');
  if(!practiceIds.length)reasons.push('No reviewed practice item is registered on this route.');
  if(!checkIds.length)reasons.push('No reviewed check item is registered on this route.');
  return {chapterId:chapter.chapterId,chapterTitle:chapter.title,objectiveId:facet.objectiveId,world:chapter.world,topicIds:[...facet.topicIds],scope:facet.scope,
    available:reasons.length===0,blockedReasons:reasons,practiceIds,checkIds,laterIds,
    instruction:reasons.length===0,practice:reasons.length===0,checkpoint:reasons.length===0,review:reasons.length===0&&laterIds.length>0};
}

/** Use the actual active content registry plus actual published routes:
 * buildExpansionCoverage({registry:AceDATContent,
 *   activeRoutes:AceDATRealms.flatMap(realm=>realm.routes)}).
 * Passing a draft module, a title, a Canon count, or nothing changes no status.
 */
export function buildExpansionCoverage({registry={},activeRoutes=[],mappings=CHAPTER_TOPIC_MAPPINGS,canonSourceSupport=CANON_SOURCE_SUPPORT}={}){
  const diagnostics=[],objectives=indexRecords(registry.objectives,diagnostics,'objective'),items=indexRecords(registry.items,diagnostics,'item'),routes=indexRecords(activeRoutes,diagnostics,'route');
  const allBase=[...baselineScreenshots,...baselineOfficial],baseById=new Map(allBase.map(t=>[t.id,t])),facets=[];
  for(const chapter of mappings){for(const facet of chapter.facets){
    if(!facet.topicIds.length||facet.topicIds.some(id=>!baseById.has(id)||baseById.get(id).world!==chapter.world))throw new Error('Coverage mapping must use an exact same-subject baseline topic ID: '+facet.objectiveId);
    facets.push(inspectFacet(chapter,facet,routes.get(chapter.chapterId),objectives,items,registry.teachingByObjective));
  }}
  const sourceById=new Map((canonSourceSupport?.topics||[]).map(r=>[r.topicId,r]));
  const merge=base=>{
    const planned=facets.filter(f=>f.topicIds.includes(base.id)),available=planned.filter(f=>f.available),row=clone(base);
    row.baselineStatus=base.status;row.status=base.status==='partial'||available.length?'partial':'planned';
    row.instruction=base.instruction||available.length>0;row.practice=base.practice||available.length>0;row.checkpoint=base.checkpoint||available.length>0;row.review=base.review||available.some(f=>f.review);
    row.expansionFacets=available.map(f=>clone(f));row.pendingExpansionFacets=planned.filter(f=>!f.available).map(f=>clone(f));
    row.objectiveIds=unique([...base.objectiveIds,...available.map(f=>f.objectiveId)]);
    row.evidenceItemIds=unique([...base.evidenceItemIds,...available.flatMap(f=>[...f.practiceIds,...f.checkIds,...f.laterIds])]);
    row.activeExpansionChapters=unique(available.map(f=>f.chapterTitle));
    if(available.length){const scope=available.map(f=>f.scope).join(' ');row.note=(base.status==='partial'?base.note+' Additional registered facets: ':'Partial game coverage: ')+scope+' This does not complete the source heading.';}
    row.canonSourceSupport=sourceById.has(base.id)?clone(sourceById.get(base.id)):null;
    return row;
  };
  const screenshotTopics=baselineScreenshots.map(merge),officialOnlyTopics=baselineOfficial.map(merge);
  const count=rows=>({total:rows.length,partial:rows.filter(r=>r.status==='partial').length,planned:rows.filter(r=>r.status==='planned').length,complete:0});
  const available=facets.filter(f=>f.available);
  const planQueue=[...screenshotTopics,...officialOnlyTopics].map(row=>({topicId:row.id,title:row.title,world:row.world,evidenceBasis:row.id.startsWith('bootcamp-')?'provided-screenshot-heading':'official-scope-group',
    gameStatus:row.status,broadObjectiveScope:row.objectiveScope,activeFacets:row.expansionFacets.map(f=>({objectiveId:f.objectiveId,scope:f.scope})),
    pendingFacets:row.pendingExpansionFacets.map(f=>({objectiveId:f.objectiveId,scope:f.scope,blockedReasons:f.blockedReasons})),
    nextWork:'Review and implement remaining facets beyond the explicitly available game scope; no whole-heading completion is established.',
    canonSourceSupport:row.canonSourceSupport}));
  return {schema:'ace-dat-game-coverage/1',screenshotTopics,officialOnlyTopics,counts:{baseline:{...BASELINE_COUNTS},screenshots:count(screenshotTopics),officialOnly:count(officialOnlyTopics),activeExpansionObjectives:unique(available.map(f=>f.objectiveId)).length,activeExpansionChapters:unique(available.map(f=>f.chapterId)).length},
    newEvidenceItemIds:unique(available.flatMap(f=>[...f.practiceIds,...f.checkIds,...f.laterIds])),facets,planQueue,diagnostics,
    canonSourceSupport:clone(canonSourceSupport),policy:'Partial describes available content for the listed facets, never learner mastery, readiness or complete coverage. Canon source support does not advance game coverage.'};
}

